void reverse(int a[], int n) {
    for (int i = 0; i < n / 2; i++) {
        int t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
}

void reverse(int a[], int n) {
    int i = 0;
    int j = n - 1;
    while (i < j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
        i++;
        j--;
    }
}

void reverse(int a[], int n) {
    int i = 0;
    while (i < n / 2) {
        int t = a[n - 1 - i];
        a[n - 1 - i] = a[i];
        a[i] = t;
        i++;
    }
}
